package com.bananalab.lite;
import android.content.*;import java.io.*;import java.util.*;import java.util.zip.*;import java.security.*;import org.json.*;
/** Streaming knowledge-only archive, separate from the bounded legacy code JSON. */
final class NotebookArchive{
 static final int MANIFEST_LIMIT=16777216;
 static void write(Context c,File target)throws Exception{write(NotebookDisk.of(c),target);}
 static void write(NotebookDisk disk,File target)throws Exception{synchronized(disk){List<NotebookDisk.Doc> docs=disk.index.list(NotebookDisk.MAX_DOCUMENTS);JSONArray rows=new JSONArray();for(NotebookDisk.Doc d:docs)rows.put(d.json());byte[] manifest=new JSONObject().put("version",1).put("last",disk.index.meta("last")).put("documents",rows).toString().getBytes("UTF-8");if(manifest.length>MANIFEST_LIMIT)throw new IOException("Índice de respaldo demasiado grande");File part=new File(target.getAbsolutePath()+".part");boolean complete=false;try{try(ZipOutputStream out=new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(part)))){entry(out,"manifest.json");out.write(manifest);out.closeEntry();byte[] buffer=new byte[65536];for(NotebookDisk.Doc d:docs){entry(out,"documents/"+d.id+".txt");MessageDigest sha=MessageDigest.getInstance("SHA-256");long bytes=0;try(InputStream in=new FileInputStream(disk.file(d))){int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Respaldo cancelado");bytes+=n;if(bytes>d.bytes)throw new IOException("Cambió el documento durante el respaldo");sha.update(buffer,0,n);out.write(buffer,0,n);}}if(bytes!=d.bytes||!NotebookDisk.hex(sha.digest()).equals(d.sha))throw new IOException("El documento no coincide con su huella guardada; conservé los originales");out.closeEntry();}}
 if(target.exists()||!part.renameTo(target))throw new IOException("No pude completar el respaldo");complete=true;}finally{if(!complete)part.delete();}}}
 static void entry(ZipOutputStream out,String name)throws Exception{ZipEntry e=new ZipEntry(name);e.setTime(315619200000L);out.putNextEntry(e);}
 static byte[] limited(InputStream in,int limit)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("El índice del respaldo supera el límite");out.write(b,0,n);}return out.toByteArray();}
 static String restore(Context c,InputStream in,boolean onlyIfAbsent)throws Exception{return restore(NotebookDisk.of(c),in,onlyIfAbsent);}
 static String restore(NotebookDisk disk,InputStream source,boolean onlyIfAbsent)throws Exception{synchronized(disk){try(ZipInputStream zip=new ZipInputStream(new BufferedInputStream(source))){if(onlyIfAbsent&&disk.initialized())return "Conservé la biblioteca privada existente.";ZipEntry first=zip.getNextEntry();if(first==null||!first.getName().equals("manifest.json"))throw new IOException("Respaldo de conocimiento sin índice inicial");JSONObject manifest=new JSONObject(new String(limited(zip,MANIFEST_LIMIT),"UTF-8"));RuntimeProgram.keys(manifest,"version","last","documents");if(manifest.getInt("version")!=1)throw new IOException("Versión de respaldo desconocida");JSONArray rows=manifest.getJSONArray("documents");if(rows.length()>NotebookDisk.MAX_DOCUMENTS)throw new IOException("Demasiados documentos");LinkedHashMap<String,NotebookDisk.Doc> expected=new LinkedHashMap<>();long declared=0;List<NotebookDisk.Doc> proposed=new ArrayList<>();for(int i=0;i<rows.length();i++){NotebookDisk.Doc d=NotebookDisk.Doc.read(rows.getJSONObject(i));if(expected.put("documents/"+d.id+".txt",d)!=null)throw new IOException("Documento repetido en el índice");declared+=d.bytes;if(declared>NotebookDisk.TOTAL_BYTES)throw new IOException("El respaldo supera512MiB de texto");proposed.add(d);}String last=manifest.getString("last");if(!last.isEmpty()&&!expected.containsKey("documents/"+last+".txt"))throw new IOException("Última fuente inválida");disk.capacity(proposed,true);String previous=disk.index.meta("last");if(disk.index.get(previous)!=null)last=previous;List<NotebookDisk.Stage> stages=new ArrayList<>();Set<String> seen=new HashSet<>();try{ZipEntry e;while((e=zip.getNextEntry())!=null){NotebookDisk.Doc d=expected.get(e.getName());if(d==null||e.isDirectory()||!seen.add(e.getName()))throw new IOException("Entrada desconocida o repetida en el respaldo");InputStream item=new FilterInputStream(zip){public void close(){}};NotebookDisk.Stage s=disk.stage(d.title,NotebookDisk.reader(item),d.source,d.origin,d.saved);stages.add(s);if(s.doc.bytes!=d.bytes||s.doc.chars!=d.chars||!s.doc.sha.equals(d.sha))throw new IOException("La huella o tamaño del documento no coincide; no importé una parte");d.file=s.doc.file;s.doc=d;}if(seen.size()!=expected.size())throw new IOException("Faltan documentos en el respaldo");disk.install(stages,true,true,last);return "Restauré el respaldo por documentos. Conservé las fuentes privadas con el mismo identificador y añadí las que faltaban.";}finally{for(NotebookDisk.Stage s:stages)disk.discardIfUnused(s);}}}}
 static void bootstrap(Context c)throws Exception{NotebookDisk disk=NotebookDisk.of(c);if(disk.initialized())return;try(InputStream in=c.getAssets().open("banana-notebook/library.zip")){restore(disk,in,true);}catch(FileNotFoundException absent){}}
 static File export(Context c)throws Exception{File f=new File(c.getDir("apk-build",0),"Banana-conocimiento-"+UUID.randomUUID()+".zip");write(c,f);c.getSharedPreferences("banana-notebook-files",0).edit().putString("export",f.getAbsolutePath()).commit();return f;}
}
